import {defaults,validateSnapshot,valueCompany,validDate} from './engine.js';
export const REQUIRED_TICKERS=['AAPL','MSFT','AMZN','GOOG','META','NVDA','TSLA','COHR','LITE','AAOI','NBIS','MU','AVGO','TSM'];
export function currentSnapshot(company,raw){
 const f=raw?.facts||{};const number=(...v)=>v.find(x=>typeof x==='number'&&Number.isFinite(x))??null;
 return {ticker:company.ticker,name:company.name,modelType:raw?.modelType||company.modelType,sector:raw?.sector||company.sector,currency:raw?.currency||company.currency||'',units:'millions',periodEnd:raw?.periodEnd||raw?.fiscalPeriodEnd,filedAt:raw?.filedAt||raw?.filingDate,availableFrom:raw?.availableFrom||raw?.acceptedAt||raw?.filedAt||raw?.filingDate,acceptedAt:raw?.acceptedAt,sourceUrl:raw?.sourceUrl||raw?.sourceURL||'',revenue:number(raw?.revenue,f.revenue),ebit:number(raw?.ebit,raw?.EBIT,f.operatingIncome,f.EBIT),cash:number(raw?.cash,f.cash),debt:number(raw?.debt,f.debt,f.totalDebt),shares:number(raw?.shares,f.shares,f.sharesOutstanding),shareBasis:raw?.shareBasis||'',coverShareDate:raw?.coverShareDate||raw?.sharesAsOf||raw?.sharesDate,snapshotMode:raw?.snapshotMode,backtestEligible:false,raw};
}
export function draftFor(company,raw){return {schemaVersion:5,ticker:company.ticker,snapshotId:raw?.id,step:0,cutoff:new Date().toISOString().slice(0,10),assumptions:{...defaults},notes:{},reviewed:[],bridgeReviewed:false,modelReviewed:false,normalizationDelta:0,adjustmentReason:'',adjustmentSource:'',quote:{price:null,date:'',currency:'',sourceUrl:'',basisConfirmed:false},waccWorksheet:{riskFree:null,beta:null,equityPremium:null,countryPremium:null,costOfDebt:null,debtWeight:null,tax:null},updatedAt:null};}
export function currentIssues(snapshot,draft,{includeReview=true}={}){
 const errors=validateSnapshot(snapshot);
 if(!['annual-reference','ttm','annual','FY'].includes(snapshot.snapshotMode))errors.push('Interim/YTD flows are not a full-year baseline. Select FY or TTM; do not annualize them silently.');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.cutoff)||!validDate(draft.cutoff))errors.push('Choose a valid valuation date.');
 else if(Date.parse(snapshot.availableFrom)>Date.parse(draft.cutoff+'T23:59:59.999Z'))errors.push('This filing was not available by the valuation date.');
 if(!snapshot.shareBasis)errors.push('The economic share basis is unverified.');
 const r=snapshot.raw||{};
 if(snapshot.ticker==='JPM'||/bank|insurance|financial/i.test(snapshot.sector||'')||snapshot.modelType&&snapshot.modelType!=='operating-fcff')errors.push('Financial institutions or specialist models require an equity/regulatory-capital workflow; this operating-company FCFF model is unsuitable.');
 const explicit=[...(r.hardBlockers||[]),...(r.fatalBlockers||[])];errors.push(...explicit);
 // Never infer an ADR conversion or a reporting currency from the US ticker.
 if(snapshot.ticker==='TSM'&&!r.adrConversionVerified)errors.push('TSM: reporting currency and depositary-share conversion require a verified model-specific mapping. Per-ADR valuation is withheld.');
 if(snapshot.ticker==='NBIS'&&!r.currentBusinessPerimeterVerified)errors.push('NBIS: business-perimeter comparability, funding and loss-to-profit mechanics require a specialist model. This simplified result is withheld.');
 if(draft.normalizationDelta!==0&&(!draft.adjustmentReason?.trim()||!/^https?:\/\//.test(draft.adjustmentSource||'')))errors.push('Explain and source the EBIT adjustment, or return it to zero.');
 if(includeReview&&!draft.bridgeReviewed)errors.push('Review the cash, debt, share basis and unresolved equity claims in step 7.');
 if(includeReview&&!draft.modelReviewed)errors.push('Confirm the model limitations in step 1 before calculating.');
 return [...new Set(errors)];
}
export function calculateCurrent(snapshot,draft){const errors=currentIssues(snapshot,draft);if(errors.length)throw new Error(errors.join(' '));return valueCompany({...snapshot,ebit:snapshot.ebit+draft.normalizationDelta,bridgeReviewed:true},{...draft.assumptions});}
export function quoteComparison(snapshot,draft,value){const q=draft.quote||{};if(!(typeof q.price==='number'&&Number.isFinite(q.price)&&q.price>0))return {status:'missing',message:'No verified current market price. Add a dated, sourced quote to compare.'};if(!validDate(q.date)||q.date>draft.cutoff||q.currency!==snapshot.currency||!/^https?:\/\//.test(q.sourceUrl||'')||!q.basisConfirmed)return {status:'blocked',message:'Quote comparison withheld: verify date, matching currency, source and economic share basis.'};return {status:'ready',price:q.price,date:q.date,gap:value.perShare/q.price-1,message:'Value-to-price gap, not an expected return.'};}
export function safeDraft(value,company,raw){const base=draftFor(company,raw);if(!value||typeof value!=='object'||value.schemaVersion!==5||value.ticker!==company.ticker||value.snapshotId!==raw?.id)return base;const d={...base,...value,assumptions:{...base.assumptions},notes:{},quote:{...base.quote}};for(const k of Object.keys(base.assumptions))if(typeof value.assumptions?.[k]==='number'&&Number.isFinite(value.assumptions[k]))d.assumptions[k]=value.assumptions[k];for(const [k,v]of Object.entries(value.notes||{}))if(typeof v==='string')d.notes[k]=v;d.assumptions.years=10;d.reviewed=Array.isArray(value.reviewed)?value.reviewed.filter(v=>Number.isInteger(v)&&v>=0&&v<8):[];d.step=Number.isInteger(value.step)?Math.max(0,Math.min(7,value.step)):0;d.bridgeReviewed=value.bridgeReviewed===true;d.modelReviewed=value.modelReviewed===true;d.normalizationDelta=typeof value.normalizationDelta==='number'&&Number.isFinite(value.normalizationDelta)?value.normalizationDelta:0;for(const k of ['cutoff','adjustmentReason','adjustmentSource'])if(typeof d[k]!=='string')d[k]=base[k];if(value.quote&&typeof value.quote==='object'){const q=value.quote;d.quote.price=typeof q.price==='number'&&Number.isFinite(q.price)?q.price:null;for(const k of ['date','currency','sourceUrl'])d.quote[k]=typeof q[k]==='string'?q[k]:'';d.quote.basisConfirmed=q.basisConfirmed===true;}d.waccWorksheet={...base.waccWorksheet};for(const k of Object.keys(base.waccWorksheet))if(typeof value.waccWorksheet?.[k]==='number'&&Number.isFinite(value.waccWorksheet[k]))d.waccWorksheet[k]=value.waccWorksheet[k];return d;}
export function freezeCurrent(snapshot,draft){const result=calculateCurrent(snapshot,draft);return JSON.parse(JSON.stringify({schemaVersion:5,id:globalThis.crypto?.randomUUID?.()||String(Date.now()),createdAt:new Date().toISOString(),mode:'current-research',classification:'Conditional educational valuation; sourced dated financials and user assumptions. Not investment advice or a live quote.',snapshot,draft,result,quoteComparison:quoteComparison(snapshot,draft,result)}));}
export function waccWorksheet({riskFree,beta,equityPremium,countryPremium,costOfDebt,debtWeight,tax}){const xs=[riskFree,beta,equityPremium,countryPremium,costOfDebt,debtWeight,tax];if(!xs.every(x=>typeof x==='number'&&Number.isFinite(x)))throw Error('Complete all seven worksheet inputs.');if(beta<0||riskFree<0||equityPremium<0||countryPremium<0||costOfDebt<0||debtWeight<0||debtWeight>1||tax<0||tax>.6)throw Error('Use nonnegative rates/beta, debt weight 0–100%, and tax 0–60%.');const costOfEquity=riskFree+beta*equityPremium+countryPremium;return {costOfEquity,afterTaxCostOfDebt:costOfDebt*(1-tax),wacc:costOfEquity*(1-debtWeight)+costOfDebt*(1-tax)*debtWeight};}
